(()=>{const paths=['shoes','hoodies','t-shirts','jackets','pants','bags','watches','electronics','accessories','other-stuff'];const grid=document.getElementById('categoryGrid');if(!grid)return;const suffix=()=>{const lang=new URLSearchParams(location.search).get('lang');return lang&&lang!=='en'?'?lang='+encodeURIComponent(lang):''};const apply=()=>grid.querySelectorAll('.category').forEach((card,index)=>{if(paths[index]){card.href='/'+paths[index]+'/'+suffix();card.dataset.categoryPage=paths[index]}});apply();new MutationObserver(apply).observe(grid,{childList:true});grid.addEventListener('click',event=>{const card=event.target.closest('[data-category-page]');if(!card)return;event.preventDefault();event.stopImmediatePropagation();location.assign(card.href)},true)})();
